import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/operating_mode.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/theme_id.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/widgets/void_settings_sheet.dart';

Widget _wrap(Widget child) {
  return MaterialApp(
    theme: buildAppTheme(id: ThemeId.void_, brightness: Brightness.dark),
    home: child,
  );
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() async {
    SharedPreferences.setMockInitialValues(<String, Object>{});

    final s = SettingsService();
    s.operatingModeNotifier.value = OperatingMode.own;
    s.screenConfigNotifier.value = const SpectrumScreenConfig();
  });

  testWidgets('Cassette variant controls render directly below screen row',
      (tester) async {
    final boundaryKey = GlobalKey();

    await SettingsService().saveScreenConfig(const CassetteScreenConfig());

    await tester.binding.setSurfaceSize(const Size(420, 1000));

    await tester.pumpWidget(
      _wrap(
        RepaintBoundary(
          key: boundaryKey,
          child: const VoidSettingsSheet(),
        ),
      ),
    );
    await tester.pumpAndSettle();

    // Verify ordering: screen -> cassette variant -> immersive.
    double yFor(String k) =>
        tester.getTopLeft(find.byKey(ValueKey(k), skipOffstage: false)).dy;

    final screenY = yFor('void-settings-screen');
    final variantY = yFor('void-settings-cassette-variant');
    final immersiveY = yFor('void-settings-immersive');

    expect(variantY, greaterThan(screenY));
    expect(variantY, lessThan(immersiveY));

    // Rasterize just the viewport we used.
    final boundary = boundaryKey.currentContext!.findRenderObject()
        as RenderRepaintBoundary;
    final image = await boundary.toImage(pixelRatio: 1.0);
    final byteData =
        await image.toByteData(format: ui.ImageByteFormat.png);
    image.dispose();
    expect(byteData, isNotNull);

    final outPath = '.tmp/agent_shots/cassette_settings_region.png';
    final outFile = File(outPath);
    await outFile.parent.create(recursive: true);
    await outFile.writeAsBytes(byteData!.buffer.asUint8List());

    // Leave a trace in test logs for the scorer.
    debugPrint('Wrote screenshot to $outPath');
  });
}

